// Firmware crypto tests (PRD 2, section 69).
//
// Run on the board itself, because they exercise mbedTLS as ESP-IDF builds it:
//
//     pio test -e xiao_esp32s3
//
// Two kinds of vector are checked:
//
//  1. RFC 9382's own test vector, which proves the SPAKE2 key schedule is the
//     standard one and not a lookalike.
//  2. A vector generated by the app's TypeScript implementation, which proves
//     the two sides agree byte for byte -- including the Wi-Fi payload, which
//     is decrypted here exactly as it arrives over BLE. The same vector is
//     pinned in mobile/tests/crossImplementation.test.ts.
//
// NOTE: these have never been executed. The robot does not exist yet, so no
// test in this directory has run on hardware.
#include <Arduino.h>
#include <unity.h>

#include "protocol.h"
#include "secure_channel.h"
#include "spake2.h"

namespace {

using namespace nura;

const String HARDWARE_ID = "NURA-3C84279A1B2C";
const String CODE = "482731";

// --- vector produced by the app's implementation ---
const char* APP_W = "1fa02665ed9b975df75bdb404d18ac479c86b98abd75b35cfaeb5ec458e03c26";
const char* APP_Y = "2222222222222222222222222222222222222222222222222222222222222222";
const char* APP_PA =
    "042a0f9510abc7ebe2f09cd14a890d6ea9a09e7c13aa654a965ea0e37e14a06e09d8528145bfb49615"
    "53e792dfc36640eb323ee89fa0f53d6f6259b831cf1caa1a";
const char* APP_PB =
    "04a2be366662ed4452539804b1582bcd21e17a9f38981f65b3b3569c610664a4d2e52aafaf588c505f"
    "bac21426616cbd8af5db8704a47564775b643d4062ad01d5";
const char* APP_KE = "da347a4571da9d8364533754b90058ef";
const char* APP_CA = "e8fbd3ba601584c0672bfe17d435036ea2ce384b65c47b67733817669d5134d6";
const char* APP_CB = "c04fdbf25ea4b9eec7be699170b43b3f9a8515045019a51aac09368572d13007";
const char* APP_WIFI_PAYLOAD =
    "010102030405060708090a0b0c35ac3270d48248323c885376a3c38c423af7b06bc2f3a73c2ed51144"
    "3320dabfed7cab53d0983bf11fb968d89469264c964fa92a6bdacea39ca54f2871e804c20ea2f2adb8"
    "df0b82a7538d827f96d5a28cbb8418a43480988439648fd37dba967abb13a0066f62df512e9375c965"
    "3d8b5bdae7055ff24cbe7e3d31f9d1cfbeee1b49ad21a42009ce4daf78d7b029bf979ad55e10a60885"
    "de9a6980cb110facd3";

// --- RFC 9382 Appendix B, the A='' B='' vector ---
const char* RFC_W = "7bf46c454b4c1b25799527d896508afd5fc62ef4ec59db1efb49113063d70cca";
const char* RFC_PA =
    "04a65b367a3f613cf9f0654b1b28a1e3a8a40387956c8ba6063e8658563890f46ca1ef6a676598889f"
    "c28de2950ab8120b79a5ef1ea4c9f44bc98f585634b46d66";
const char* RFC_PB =
    "04589f13218822710d98d8b2123a079041052d9941b9cf88c6617ddb2fcc0494662eea8ba6b64692dc"
    "318250030c6af045cb738bc81ba35b043c3dcb46adf6f58d";
const char* RFC_K =
    "041a3c03d51b452537ca2a1fea6110353c6d5ed483c4f0f86f4492ca3f378d40a994b4477f93c64d92"
    "8edbbcd3e85a7c709b7ea73ee97986ce3d1438e135543772";
const char* RFC_KE = "fc6374762ba5cf11f4b2caa08b2cd1b9";
const char* RFC_CA = "dfb4db8d48ae5a675963ea5e6c19d98d4ea028d8e898dad96ea19a80ade95dca";
const char* RFC_CB = "d0f0609d1613138d354f7e95f19fb556bf52d751947241e8c7118df5ef0ae175";

uint8_t hexDigit(char character) {
    if (character >= '0' && character <= '9') return character - '0';
    if (character >= 'a' && character <= 'f') return character - 'a' + 10;
    if (character >= 'A' && character <= 'F') return character - 'A' + 10;
    return 0;
}

size_t fromHex(const char* hex, uint8_t* out, size_t capacity) {
    const size_t length = strlen(hex) / 2;
    if (length > capacity) return 0;
    for (size_t index = 0; index < length; index += 1) {
        out[index] = (hexDigit(hex[index * 2]) << 4) | hexDigit(hex[index * 2 + 1]);
    }
    return length;
}

void assertBytesEqual(const char* expectedHex, const uint8_t* actual, size_t length) {
    uint8_t expected[128];
    const size_t expectedLength = fromHex(expectedHex, expected, sizeof(expected));
    TEST_ASSERT_EQUAL_size_t(expectedLength, length);
    TEST_ASSERT_EQUAL_UINT8_ARRAY(expected, actual, length);
}

}  // namespace

void setUp() {}
void tearDown() {}

void test_password_scalar_matches_the_app() {
    uint8_t w[32];
    TEST_ASSERT_TRUE(spake2::passwordScalar(HARDWARE_ID, CODE, w));
    assertBytesEqual(APP_W, w, sizeof(w));
}

void test_password_scalar_is_bound_to_the_device_and_the_code() {
    uint8_t mine[32];
    uint8_t otherDevice[32];
    uint8_t otherCode[32];
    TEST_ASSERT_TRUE(spake2::passwordScalar(HARDWARE_ID, CODE, mine));
    TEST_ASSERT_TRUE(spake2::passwordScalar("NURA-3C84279AFFFF", CODE, otherDevice));
    TEST_ASSERT_TRUE(spake2::passwordScalar(HARDWARE_ID, "482732", otherCode));

    TEST_ASSERT_FALSE(spake2::constantTimeEquals(mine, otherDevice, 32));
    TEST_ASSERT_FALSE(spake2::constantTimeEquals(mine, otherCode, 32));
}

void test_key_schedule_matches_rfc9382() {
    uint8_t pA[65];
    uint8_t pB[65];
    uint8_t shared[65];
    uint8_t w[32];
    fromHex(RFC_PA, pA, sizeof(pA));
    fromHex(RFC_PB, pB, sizeof(pB));
    fromHex(RFC_K, shared, sizeof(shared));
    fromHex(RFC_W, w, sizeof(w));

    uint8_t ke[16];
    uint8_t cA[32];
    uint8_t cB[32];
    // The RFC's vector uses empty identities and no associated data.
    TEST_ASSERT_TRUE(spake2::keySchedule(nullptr, 0, nullptr, 0, pA, pB, shared, w, nullptr, 0,
                                         ke, cA, cB));

    assertBytesEqual(RFC_KE, ke, sizeof(ke));
    assertBytesEqual(RFC_CA, cA, sizeof(cA));
    assertBytesEqual(RFC_CB, cB, sizeof(cB));
}

void test_exchange_matches_the_app_byte_for_byte() {
    uint8_t pA[65];
    uint8_t y[32];
    fromHex(APP_PA, pA, sizeof(pA));
    fromHex(APP_Y, y, sizeof(y));

    spake2::Session session;
    TEST_ASSERT_TRUE(
        spake2::respondWithScalar(HARDWARE_ID, CODE, pA, sizeof(pA), y, sizeof(y), session));

    assertBytesEqual(APP_PB, session.pB, sizeof(session.pB));
    assertBytesEqual(APP_CA, session.cA, sizeof(session.cA));
    assertBytesEqual(APP_CB, session.cB, sizeof(session.cB));
    assertBytesEqual(APP_KE, session.ke, sizeof(session.ke));
}

void test_rejects_a_point_that_is_not_on_the_curve() {
    uint8_t bogus[65] = {0};
    bogus[0] = 0x04;
    bogus[64] = 0x01;

    spake2::Session session;
    TEST_ASSERT_FALSE(spake2::respond(HARDWARE_ID, CODE, bogus, sizeof(bogus), session));
}

void test_rejects_a_malformed_message() {
    uint8_t truncated[10] = {0x04};
    spake2::Session session;
    TEST_ASSERT_FALSE(spake2::respond(HARDWARE_ID, CODE, truncated, sizeof(truncated), session));
    TEST_ASSERT_FALSE(spake2::respond(HARDWARE_ID, CODE, nullptr, 0, session));
}

void test_wifi_payload_from_the_app_decrypts() {
    uint8_t ke[16];
    uint8_t payload[512];
    fromHex(APP_KE, ke, sizeof(ke));
    const size_t payloadLength = fromHex(APP_WIFI_PAYLOAD, payload, sizeof(payload));

    uint8_t key[16];
    TEST_ASSERT_TRUE(secure_channel::deriveWifiKey(ke, key));

    secure_channel::WifiConfig config;
    TEST_ASSERT_TRUE(
        secure_channel::openWifiConfig(key, HARDWARE_ID, payload, payloadLength, config));

    TEST_ASSERT_EQUAL_STRING("Home Network", config.ssid.c_str());
    TEST_ASSERT_EQUAL_STRING("correct horse battery staple", config.password.c_str());
    TEST_ASSERT_EQUAL_STRING("npt_testtoken", config.provisioningToken.c_str());
    TEST_ASSERT_EQUAL_STRING("http://192.168.1.20:8000", config.apiBaseUrl.c_str());
}

void test_wifi_payload_rejects_tampering() {
    uint8_t ke[16];
    uint8_t payload[512];
    fromHex(APP_KE, ke, sizeof(ke));
    const size_t payloadLength = fromHex(APP_WIFI_PAYLOAD, payload, sizeof(payload));
    uint8_t key[16];
    secure_channel::deriveWifiKey(ke, key);

    payload[30] ^= 0xFF;
    secure_channel::WifiConfig config;
    TEST_ASSERT_FALSE(
        secure_channel::openWifiConfig(key, HARDWARE_ID, payload, payloadLength, config));
}

void test_wifi_payload_cannot_be_replayed_at_another_robot() {
    uint8_t ke[16];
    uint8_t payload[512];
    fromHex(APP_KE, ke, sizeof(ke));
    const size_t payloadLength = fromHex(APP_WIFI_PAYLOAD, payload, sizeof(payload));
    uint8_t key[16];
    secure_channel::deriveWifiKey(ke, key);

    secure_channel::WifiConfig config;
    TEST_ASSERT_FALSE(
        secure_channel::openWifiConfig(key, "NURA-3C84279AFFFF", payload, payloadLength, config));
}

void test_constant_time_compare() {
    const uint8_t a[4] = {1, 2, 3, 4};
    const uint8_t b[4] = {1, 2, 3, 4};
    const uint8_t c[4] = {1, 2, 3, 5};
    TEST_ASSERT_TRUE(spake2::constantTimeEquals(a, b, sizeof(a)));
    TEST_ASSERT_FALSE(spake2::constantTimeEquals(a, c, sizeof(a)));
}

void setup() {
    // Give the USB serial port time to enumerate before the results go out.
    delay(2000);
    UNITY_BEGIN();
    RUN_TEST(test_password_scalar_matches_the_app);
    RUN_TEST(test_password_scalar_is_bound_to_the_device_and_the_code);
    RUN_TEST(test_key_schedule_matches_rfc9382);
    RUN_TEST(test_exchange_matches_the_app_byte_for_byte);
    RUN_TEST(test_rejects_a_point_that_is_not_on_the_curve);
    RUN_TEST(test_rejects_a_malformed_message);
    RUN_TEST(test_wifi_payload_from_the_app_decrypts);
    RUN_TEST(test_wifi_payload_rejects_tampering);
    RUN_TEST(test_wifi_payload_cannot_be_replayed_at_another_robot);
    RUN_TEST(test_constant_time_compare);
    UNITY_END();
}

void loop() {}
